-- V3__seed_exercise_library.sql
-- Seed 100+ normalized exercises across all 11 muscle groups + Traps + Cardio
-- Open dataset attribution: free-exercise-db (Public Domain / CC0)

MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=600', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400', 'Lie flat on the bench with eyes directly under the racked bar. Plant feet firmly on the floor.', '["Lie flat on the bench with eyes directly under the racked bar. Plant feet firmly on the floor.","Grip the bar slightly wider than shoulder-width with thumbs wrapped securely.","Unrack the bar, retract and depress your scapulae, and bring bar directly over upper chest.","Lower the bar with controlled tempo to touch your mid-to-lower sternum with elbows tucked at 45-75 degrees.","Press powerfully upward driving through your chest and triceps back to starting position."]', '["Bouncing the bar violently off the sternum.","Flaring elbows outward 90 degrees risking shoulder impingement.","Lifting glutes off the bench to cheat leverage."]', 4, '6-8', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Incline Dumbbell Press', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?w=600', 'https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?w=400', 'Set an adjustable bench to an incline of 30 degrees (avoid steep 45+ degree angles).', '["Set an adjustable bench to an incline of 30 degrees (avoid steep 45+ degree angles).","Kick dumbbells up to shoulder level using your knees as you lie back.","Press dumbbells up in a slight arc until arms are extended but not hyper-locked.","Lower weights smoothly until you feel an active stretch in the upper clavicular pectoralis.","Press back up while driving your feet through the floor and keeping ribcage proud."]', '["Setting bench angle too high (>45°), turning it into a front delt press.","Clanking dumbbells together at the top losing muscular tension."]', 3, '8-12', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternating Floor Press', 'CHEST', 'ABS,SHOULDERS,TRICEPS', 'KETTLEBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Floor_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Floor_Press/0.jpg', 'Lie on the floor with two kettlebells next to your shoulders.', '["Lie on the floor with two kettlebells next to your shoulders.","Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.","Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.","Raise the kettlebell and repeat on the opposite side."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Around The Worlds', 'CHEST', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Around_The_Worlds/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Around_The_Worlds/0.jpg', 'Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.', '["Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.","Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.","Reverse the movement to return the weight to the starting position as you exhale."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Bench Press - Medium Grip', 'CHEST', 'SHOULDERS,TRICEPS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg', 'Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', '["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.","After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Guillotine Bench Press', 'CHEST', 'SHOULDERS,TRICEPS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Guillotine_Bench_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Guillotine_Bench_Press/0.jpg', 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.', '["Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.","As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Incline Bench Press - Medium Grip', 'CHEST', 'SHOULDERS,TRICEPS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg', 'Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', '["Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on you upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Behind Head Chest Stretch', 'CHEST', 'SHOULDERS', 'MACHINE', 'ADVANCED', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Behind_Head_Chest_Stretch/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Behind_Head_Chest_Stretch/0.jpg', 'Sit upright on the floor with your partner behind you.', '["Sit upright on the floor with your partner behind you.","Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position.","Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving.","Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 4, '6-10', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bench Press - With Bands', 'CHEST', 'SHOULDERS,TRICEPS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_With_Bands/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_With_Bands/0.jpg', 'Using a flat bench secure a band under the leg of the bench that is nearest to your head.', '["Using a flat bench secure a band under the leg of the bench that is nearest to your head.","Once the band is secure, grab it by both handles and lie down on the bench.","Extend your arms so that you are holding the band handles in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.","As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bent-Arm Dumbbell Pullover', 'CHEST', 'BACK,SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Dumbbell_Pullover/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Arm_Dumbbell_Pullover/0.jpg', 'Place a dumbbell standing up on a flat bench.', '["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.","Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.","While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bodyweight Flyes', 'CHEST', 'ABS,SHOULDERS,TRICEPS', 'EZ_BAR', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Flyes/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bodyweight_Flyes/0.jpg', 'Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.', '["Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.","Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.","Place your hands on the bars. This will be your starting position.","Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.","After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Butterfly', 'CHEST', '', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butterfly/0.jpg', 'Sit on the machine with your back flat on the pad.', '["Sit on the machine with your back flat on the pad.","Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.","Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.","Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.","Repeat for the recommended amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable Chest Press', 'CHEST', 'SHOULDERS,TRICEPS', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Chest_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Chest_Press/0.jpg', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', '["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to th starting position, keeping tension on the cables.","You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable Crossover', 'CHEST', 'SHOULDERS', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Crossover/0.jpg', 'To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.', '["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.","Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Conventional Barbell Deadlift', 'BACK', 'HAMSTRINGS,GLUTES,FOREARMS,TRAPS', 'BARBELL', 'ADVANCED', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=600', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400', 'Stand with mid-foot directly under the barbell, feet hip-width apart.', '["Stand with mid-foot directly under the barbell, feet hip-width apart.","Hinge at hips, grip the bar just outside your knees with double overhand or hook grip.","Bring shins to touch the bar without moving it. Pull chest up, retract lats to pull out slack.","Take a deep diaphragmatic breath, brace core 360 degrees, and push floor away with your legs.","Lock out hips and knees simultaneously. Reverse movement by hinging hips back."]', '["Rounding the lumbar spine under heavy loads.","Letting the bar drift forward away from shins and thighs.","Hyperextending the lumbar spine at lockout."]', 4, '5', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Lat Pulldown', 'BACK', 'BICEPS,FOREARMS,SHOULDERS', 'CABLE', 'BEGINNER', 'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?w=600', 'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?w=400', 'Adjust thigh pads so your legs are locked securely with flat feet.', '["Adjust thigh pads so your legs are locked securely with flat feet.","Grip the bar slightly wider than shoulder width with an overhand grip.","Lean back slightly (10-15 degrees), depress your shoulder blades, and pull elbows straight down towards ribs.","Touch the bar to your upper chest while squeezing the latissimus dorsi.","Control the return upward with a 2-second stretch at the top."]', '["Swinging backward with momentum to yank the weight down.","Pulling the bar behind the neck, causing excessive cervical spine strain."]', 3, '10-12', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Power Clean', 'BACK', 'TRAPS,GLUTES,HAMSTRINGS,SHOULDERS,QUADRICEPS', 'BARBELL', 'ADVANCED', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=600', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400', 'Start in a deadlift stance with bar over mid-foot, hook grip on the bar.', '["Start in a deadlift stance with bar over mid-foot, hook grip on the bar.","Pull bar smoothly off the floor to mid-thigh maintaining upright torso angle.","Explosively extend hips, knees, and ankles (triple extension) with an aggressive trap shrug.","Pull yourself rapidly under the bar, snapping elbows forward to catch bar on front deltoids in a quarter squat.","Stand fully erect, then return bar safely."]', '["Catching the bar with low, drooping elbows risking wrist injury.","Reverse-curling the bar rather than driving with triple hip extension."]', 4, '3-5', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cat-Cow Mobility Flow', 'BACK', 'ABS,SHOULDERS', 'BODYWEIGHT', 'BEGINNER', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=600', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=400', 'Start on hands and knees with wrists under shoulders and knees under hips.', '["Start on hands and knees with wrists under shoulders and knees under hips.","Inhale: Drop belly toward floor, lift chest, arch back, and look up (Cow Pose).","Exhale: Tuck chin to chest, round spine toward ceiling, and pull navel to spine (Cat Pose).","Move fluidly with breath for 10-15 cycles."]', '["Forcing end-range cervical hyperextension.","Locking out elbows instead of maintaining a soft flex."]', 2, '10 cycles', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternating Kettlebell Row', 'BACK', 'BICEPS', 'KETTLEBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Row/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Kettlebell_Row/0.jpg', 'Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.', '["Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.","Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.","Lower the kettlebell in the working arm and repeat with your other arm."]', '["Yanking with lower back momentum rather than initiating with scapular retraction.","Shrugging shoulders into the neck instead of driving elbows back towards hip pocket."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternating Renegade Row', 'BACK', 'ABS,BICEPS,CHEST,TRICEPS', 'KETTLEBELL', 'ADVANCED', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Renegade_Row/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Renegade_Row/0.jpg', 'Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.', '["Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.","Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.","Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps."]', '["Yanking with lower back momentum rather than initiating with scapular retraction.","Shrugging shoulders into the neck instead of driving elbows back towards hip pocket."]', 4, '6-10', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Atlas Stone Trainer', 'BACK', 'BICEPS,FOREARMS,GLUTES,HAMSTRINGS,QUADRICEPS', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Atlas_Stone_Trainer/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Atlas_Stone_Trainer/0.jpg', 'This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.', '["This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.","Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.","Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.","Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Atlas Stones', 'BACK', 'ABS,QUADRICEPS,BICEPS,CALVES,FOREARMS,GLUTES,HAMSTRINGS,TRAPS', 'MACHINE', 'ADVANCED', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Atlas_Stones/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Atlas_Stones/0.jpg', 'Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.', '["Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.","Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.","As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.","Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 4, '6-10', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Axle Deadlift', 'BACK', 'FOREARMS,GLUTES,HAMSTRINGS,QUADRICEPS,TRAPS', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Axle_Deadlift/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Axle_Deadlift/0.jpg', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.', '["Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.","With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.","After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."]', '["Rounding the lower back when breaking the bar off the floor.","Letting the barbell drift far away from shins during the pull.","Hyperextending the lower back at lockout rather than squeezing glutes through."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Band Assisted Pull-Up', 'BACK', 'ABS,FOREARMS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Assisted_Pull-Up/0.jpg', 'Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.', '["Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.","Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.","Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.","After a brief pause, return to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Deadlift', 'BACK', 'CALVES,FOREARMS,GLUTES,HAMSTRINGS,QUADRICEPS,TRAPS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Deadlift/0.jpg', 'Stand in front of a loaded barbell.', '["Stand in front of a loaded barbell.","While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.","While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.","Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.","Perform the amount of repetitions prescribed in the program."]', '["Rounding the lower back when breaking the bar off the floor.","Letting the barbell drift far away from shins during the pull.","Hyperextending the lower back at lockout rather than squeezing glutes through."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bent-Arm Barbell Pullover', 'BACK', 'CHEST,SHOULDERS,TRICEPS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Barbell_Pullover/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Arm_Barbell_Pullover/0.jpg', 'Lie on a flat bench with a barbell using a shoulder grip width.', '["Lie on a flat bench with a barbell using a shoulder grip width.","Hold the bar straight over your chest with a bend in your arms. This will be your starting position.","While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bent Over Barbell Row', 'BACK', 'BICEPS,SHOULDERS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Barbell_Row/0.jpg', 'Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', '["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.","Then inhale and slowly lower the barbell back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Yanking with lower back momentum rather than initiating with scapular retraction.","Shrugging shoulders into the neck instead of driving elbows back towards hip pocket."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bent Over One-Arm Long Bar Row', 'BACK', 'BICEPS,TRAPS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_One-Arm_Long_Bar_Row/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_One-Arm_Long_Bar_Row/0.jpg', 'Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.', '["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.","Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.","Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.","Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).","Repeat for the recommended amount of repetitions and switch arms."]', '["Yanking with lower back momentum rather than initiating with scapular retraction.","Shrugging shoulders into the neck instead of driving elbows back towards hip pocket."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Shrug', 'TRAPS', 'FOREARMS', 'BARBELL', 'BEGINNER', 'https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?w=600', 'https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?w=400', 'Stand upright holding a barbell at shoulder width in front of your thighs.', '["Stand upright holding a barbell at shoulder width in front of your thighs.","Keep arms straight without bending elbows.","Elevate your shoulders straight up toward your ears in a pure vertical plane.","Hold the peak contraction for 1-2 seconds, then lower under full control."]', '["Rolling shoulders in circular motions which creates rotator cuff friction without extra trap loading.","Bending elbows to pull weight up."]', 4, '12-15', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Farmer''s Walk', 'TRAPS', 'FOREARMS,ABS,GLUTES', 'DUMBBELL', 'INTERMEDIATE', 'https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?w=600', 'https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?w=400', 'Deadlift heavy dumbbells or kettlebells from the floor with neutral posture.', '["Deadlift heavy dumbbells or kettlebells from the floor with neutral posture.","Keep chest tall, shoulders packed down and back, and core braced tight.","Walk forward with steady, short, controlled heel-to-toe strides for 30-60 seconds.","Lower weights safely with a clean hip hinge."]', '["Allowing shoulders to slump forward or hunching neck.","Taking long, unstable strides that compromise spinal alignment."]', 3, '40m walk', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Shrug Behind The Back', 'TRAPS', 'FOREARMS,BACK', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug_Behind_The_Back/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shrug_Behind_The_Back/0.jpg', 'Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.', '["Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable Shrugs', 'TRAPS', '', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Shrugs/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Shrugs/0.jpg', 'Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.', '["Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.","Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.","Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.","Lower the bar back to the original position.","Repeat for the recommended amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Calf-Machine Shoulder Shrug', 'TRAPS', '', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf-Machine_Shoulder_Shrug/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf-Machine_Shoulder_Shrug/0.jpg', 'Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.', '["Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.","Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.","Slowly return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Clean Shrug', 'TRAPS', 'FOREARMS,SHOULDERS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Shrug/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Shrug/0.jpg', 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', '["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Dumbbell Shrug', 'TRAPS', '', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shrug/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Shrug/0.jpg', 'Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.', '["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.","Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.","Lower the dumbbells back to the original position.","Repeat for the recommended amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Kettlebell Sumo High Pull', 'TRAPS', 'QUADRICEPS,GLUTES,HAMSTRINGS,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Sumo_High_Pull/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Sumo_High_Pull/0.jpg', 'Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.', '["Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.","Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Leverage Shrug', 'TRAPS', 'FOREARMS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Shrug/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leverage_Shrug/0.jpg', 'Load the pins to an appropriate weight. Position yourself directly between the handles.', '["Load the pins to an appropriate weight. Position yourself directly between the handles.","Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.","Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.","Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.","Pause at the top of the motion, and then return the weight to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Scapular Pull-Up', 'TRAPS', 'BACK', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scapular_Pull-Up/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Scapular_Pull-Up/0.jpg', 'Take a pronated grip on a pull-up bar.', '["Take a pronated grip on a pull-up bar.","From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.","Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Smith Machine Behind the Back Shrug', 'TRAPS', 'SHOULDERS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Behind_the_Back_Shrug/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Behind_the_Back_Shrug/0.jpg', 'With the bar at thigh level, load an appropriate weight.', '["With the bar at thigh level, load an appropriate weight.","Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.","Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement.","After a brief pause return the weight to the starting position.","Repeat for the desired number of repetitions before engaging the hooks to rack the weight."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Smith Machine Upright Row', 'TRAPS', 'BICEPS,BACK,SHOULDERS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Upright_Row/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Smith_Machine_Upright_Row/0.jpg', 'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.', '["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.","Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."]', '["Yanking with lower back momentum rather than initiating with scapular retraction.","Shrugging shoulders into the neck instead of driving elbows back towards hip pocket."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Snatch Shrug', 'TRAPS', 'FOREARMS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Shrug/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Snatch_Shrug/0.jpg', 'Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.', '["Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Standing Dumbbell Upright Row', 'TRAPS', 'BICEPS,SHOULDERS', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Upright_Row/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Dumbbell_Upright_Row/0.jpg', 'Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', '["Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."]', '["Yanking with lower back momentum rather than initiating with scapular retraction.","Shrugging shoulders into the neck instead of driving elbows back towards hip pocket."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Wrist Curl', 'FOREARMS', 'BICEPS', 'BARBELL', 'BEGINNER', 'https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?w=600', 'https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?w=400', 'Sit on a bench resting your forearms on your thighs with wrists hanging just over your knees.', '["Sit on a bench resting your forearms on your thighs with wrists hanging just over your knees.","Hold a barbell with an underhand grip (palms up).","Lower the bar allowing it to roll down to your fingertips for a deep forearm stretch.","Curl wrists upward as high as possible while squeezing your forearm flexors."]', '["Lifting forearms off your thighs during the curl.","Using jerky, bouncy motions that stress wrist tendons."]', 3, '15-20', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Dead Hang', 'FOREARMS', 'BACK,SHOULDERS', 'BODYWEIGHT', 'BEGINNER', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=600', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=400', 'Grab a pull-up bar using an overhand grip slightly wider than shoulders.', '["Grab a pull-up bar using an overhand grip slightly wider than shoulders.","Hang freely with feet off the floor, allowing gravity to gently decompress spine.","Keep grip clenched tight while engaging core and breathing steadily for time."]', '["Holding breath instead of diaphragmatic respiration.","Shrugging shoulders into ears without active shoulder depression."]', 3, '45-60s', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bottoms-Up Clean From The Hang Position', 'FOREARMS', 'BICEPS,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg', 'Initiate the exercise by standing upright with a kettlebell in one hand.', '["Initiate the exercise by standing upright with a kettlebell in one hand.","Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable Wrist Curl', 'FOREARMS', '', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Wrist_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Wrist_Curl/0.jpg', 'Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.', '["Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.","Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.","Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Dumbbell Lying Pronation', 'FOREARMS', '', 'DUMBBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Pronation/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Pronation/0.jpg', 'Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', '["Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.","Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Dumbbell Lying Supination', 'FOREARMS', '', 'DUMBBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Supination/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Supination/0.jpg', 'Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', '["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.","Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions and then switch to the other arm."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Finger Curls', 'FOREARMS', '', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Finger_Curls/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Finger_Curls/0.jpg', 'Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.', '["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.","Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.","Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Kneeling Forearm Stretch', 'FOREARMS', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Forearm_Stretch/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Forearm_Stretch/0.jpg', 'Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.', '["Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.","Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Palms-Down Dumbbell Wrist Curl Over A Bench', 'FOREARMS', '', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Start out by placing two dumbbells on one side of a flat bench.', '["Start out by placing two dumbbells on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Palms-Down Wrist Curl Over A Bench', 'FOREARMS', '', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg', 'Start out by placing a barbell on one side of a flat bench.', '["Start out by placing a barbell on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Palms-Up Barbell Wrist Curl Over A Bench', 'FOREARMS', '', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Start out by placing a barbell on one side of a flat bench.', '["Start out by placing a barbell on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Palms-Up Dumbbell Wrist Curl Over A Bench', 'FOREARMS', '', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Start out by placing two dumbbells on one side of a flat bench.', '["Start out by placing two dumbbells on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Plate Pinch', 'FOREARMS', '', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Pinch/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Plate_Pinch/0.jpg', 'Grab two wide-rimmed plates and put them together with the smooth sides facing outward', '["Grab two wide-rimmed plates and put them together with the smooth sides facing outward","Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.","Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.","Repeat for the recommended amount of sets prescribed in your program.","Switch arms and repeat the movements."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Rickshaw Carry', 'FOREARMS', 'ABS,CALVES,GLUTES,HAMSTRINGS,BACK,QUADRICEPS,TRAPS', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rickshaw_Carry/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Rickshaw_Carry/0.jpg', 'Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.', '["Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.","Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Seated Hip Adductor Machine', 'QUADRICEPS', 'GLUTES', 'MACHINE', 'BEGINNER', 'https://images.unsplash.com/photo-1540497077202-7c8a3999166f?w=600', 'https://images.unsplash.com/photo-1540497077202-7c8a3999166f?w=400', 'Sit in machine with back firmly supported and inner thighs placed against the pads.', '["Sit in machine with back firmly supported and inner thighs placed against the pads.","Adjust lever to comfortable wide spread for an active stretch in inner groin.","Squeeze thighs together inward until pads touch in front of you.","Hold peak squeeze for 1 second, then resist return slowly."]', '["Allowing the weight stack to slam at the stretch position.","Lifting hips off seat during the squeeze."]', 3, '12-15', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Thruster', 'QUADRICEPS', 'SHOULDERS,GLUTES,TRICEPS,ABS', 'BARBELL', 'ADVANCED', 'https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?w=600', 'https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?w=400', 'Rest barbell in front rack position across anterior deltoids, elbows high.', '["Rest barbell in front rack position across anterior deltoids, elbows high.","Descend into a full front squat below parallel with knees tracking toes.","Drive aggressively upward out of the squat, using leg drive to propel bar overhead.","Lock out arms completely overhead in one fluid transition.","Lower bar smoothly back to shoulders as you prepare for the next descent."]', '["Pausing at the top of the squat before pressing instead of a continuous fluid kinetic chain.","Collapsing chest forward during the squat descent."]', 3, '8-10', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Adductor', 'QUADRICEPS', '', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Adductor/0.jpg', 'Lie face down with one leg on a foam roll.', '["Lie face down with one leg on a foam roll.","Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.","While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Adductor/Groin', 'QUADRICEPS', '', 'BODYWEIGHT', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor_Groin/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Adductor_Groin/0.jpg', 'Lie on your back with your feet raised towards the ceiling.', '["Lie on your back with your feet raised towards the ceiling.","Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.","Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.","Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('All Fours Quad Stretch', 'QUADRICEPS', '', 'BODYWEIGHT', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/All_Fours_Quad_Stretch/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/All_Fours_Quad_Stretch/0.jpg', 'Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.', '["Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.","Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.","Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternate Leg Diagonal Bound', 'QUADRICEPS', 'ABS,CALVES,GLUTES,HAMSTRINGS', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Leg_Diagonal_Bound/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Leg_Diagonal_Bound/0.jpg', 'Assume a comfortable stance with one foot slightly in front of the other.', '["Assume a comfortable stance with one foot slightly in front of the other.","Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.","It may help to use a line on the ground to guage distance from side to side.","Repeat the sequence with the other leg."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Backward Drag', 'QUADRICEPS', 'CALVES,FOREARMS,GLUTES,HAMSTRINGS,BACK', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Drag/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Backward_Drag/0.jpg', 'Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.', '["Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.","Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Band Hip Adductions', 'QUADRICEPS', '', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Hip_Adductions/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Hip_Adductions/0.jpg', 'Anchor a band around a solid post or other object.', '["Anchor a band around a solid post or other object.","Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.","Stand up straight and hold onto the post if needed. This will be your starting position.","Keeping the knee straight, raise your right legs out to the side as far as you can.","Return to the starting position and repeat for the desired rep count.","Switch sides."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Full Squat', 'QUADRICEPS', 'CALVES,GLUTES,HAMSTRINGS,BACK', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Full_Squat/0.jpg', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.","Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.","Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Allowing knees to cave inward (valgus collapse) during the upward drive phase.","Lifting heels off the ground and shifting weight excessively onto toes.","Rounding the lumbar spine at the bottom instead of maintaining neutral spinal bracing."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Hack Squat', 'QUADRICEPS', 'CALVES,FOREARMS,HAMSTRINGS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hack_Squat/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Hack_Squat/0.jpg', 'Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', '["Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.","While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.","Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.","Repeat for the recommended amount of repetitions."]', '["Allowing knees to cave inward (valgus collapse) during the upward drive phase.","Lifting heels off the ground and shifting weight excessively onto toes.","Rounding the lumbar spine at the bottom instead of maintaining neutral spinal bracing."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Lunge', 'QUADRICEPS', 'CALVES,GLUTES,HAMSTRINGS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Lunge/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Lunge/0.jpg', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."]', '["Letting front knee collapse inwards or driving solely through toes.","Leaning aggressively sideways instead of keeping pelvis squared."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Side Split Squat', 'QUADRICEPS', 'CALVES,HAMSTRINGS,BACK', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Split_Squat/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Split_Squat/0.jpg', 'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.', '["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.","Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.","Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.","After performing the recommended amount of reps, repeat the movement with the opposite leg."]', '["Allowing knees to cave inward (valgus collapse) during the upward drive phase.","Lifting heels off the ground and shifting weight excessively onto toes.","Rounding the lumbar spine at the bottom instead of maintaining neutral spinal bracing."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Squat', 'QUADRICEPS', 'CALVES,GLUTES,HAMSTRINGS,BACK', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Squat/0.jpg', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Allowing knees to cave inward (valgus collapse) during the upward drive phase.","Lifting heels off the ground and shifting weight excessively onto toes.","Rounding the lumbar spine at the bottom instead of maintaining neutral spinal bracing."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Squat To A Bench', 'QUADRICEPS', 'CALVES,GLUTES,HAMSTRINGS,BACK', 'BARBELL', 'ADVANCED', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat_To_A_Bench/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Squat_To_A_Bench/0.jpg', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.","","Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Seated Hip Abductor Machine', 'GLUTES', 'QUADRICEPS', 'MACHINE', 'BEGINNER', 'https://images.unsplash.com/photo-1540497077202-7c8a3999166f?w=600', 'https://images.unsplash.com/photo-1540497077202-7c8a3999166f?w=400', 'Sit upright with back supported and outer thighs against pads.', '["Sit upright with back supported and outer thighs against pads.","Push thighs outward laterally against resistance focusing on outer gluteus medius.","Pause at maximum abduction, then slowly control return to center."]', '["Using aggressive jerky momentum instead of isolated outer hip contraction."]', 3, '12-15', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Kettlebell Swing', 'GLUTES', 'HAMSTRINGS,BACK,FOREARMS,ABS', 'KETTLEBELL', 'INTERMEDIATE', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=600', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400', 'Stand feet shoulder-width apart, kettlebell placed 1 foot in front on floor.', '["Stand feet shoulder-width apart, kettlebell placed 1 foot in front on floor.","Hinge at hips, reach forward with both hands and tilt bell towards you.","Hike bell between your legs like a center in football.","Snap hips forward with powerful glute contraction to propel bell to chest level.","Let bell swing back naturally into the hip hinge without squatting."]', '["Squatting the weight rather than performing a pure horizontal hip hinge.","Lifting with shoulders and arms rather than hip drive."]', 4, '15-20', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('90/90 Hip Mobility', 'GLUTES', 'QUADRICEPS,HAMSTRINGS', 'BODYWEIGHT', 'BEGINNER', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=600', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=400', 'Sit on floor with front leg bent at 90-degree angle and back leg bent at 90-degree angle.', '["Sit on floor with front leg bent at 90-degree angle and back leg bent at 90-degree angle.","Keep torso tall with proud chest, squaring shoulders toward front shin.","Hinge forward from hips over front leg to stretch lead hip, hold 30s.","Transition smoothly across center to opposite side without using hands if possible."]', '["Slumping and rounding lumbar spine rather than hinging at hips."]', 2, '45s per side', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Ankle On The Knee', 'GLUTES', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_On_The_Knee/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ankle_On_The_Knee/0.jpg', 'From a lying position, bend your knees and keep your feet on the floor.', '["From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Glute Bridge', 'GLUTES', 'CALVES,HAMSTRINGS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Glute_Bridge/0.jpg', 'Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.', '["Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.","Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.","Extend as far as possible, then reverse the motion to return to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Hip Thrust', 'GLUTES', 'CALVES,HAMSTRINGS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Hip_Thrust/0.jpg', 'Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.', '["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.","Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.","Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Butt Lift (Bridge)', 'GLUTES', 'HAMSTRINGS', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt_Lift_Bridge/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt_Lift_Bridge/0.jpg', 'Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.', '["Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.","Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.","Slowly go back to the starting position as you breathe in."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Downward Facing Balance', 'GLUTES', 'ABS,HAMSTRINGS', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Downward_Facing_Balance/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Downward_Facing_Balance/0.jpg', 'Lie facedown on top of an exercise ball.', '["Lie facedown on top of an exercise ball.","While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Flutter Kicks', 'GLUTES', 'HAMSTRINGS', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flutter_Kicks/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flutter_Kicks/0.jpg', 'On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.', '["On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.","Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.","Start the movement by lifting the left leg higher than the right leg.","Then lower the left leg as you lift the right leg.","Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Glute Kickback', 'GLUTES', 'HAMSTRINGS', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Glute_Kickback/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Glute_Kickback/0.jpg', 'Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.', '["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Hip Extension with Bands', 'GLUTES', 'HAMSTRINGS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Extension_with_Bands/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Extension_with_Bands/0.jpg', 'Secure one end of the band to the lower portion of a post and attach the other to one ankle.', '["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Facing the attachment point of the band, hold on to the column to stabilize yourself.","Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.","Return the leg to the starting position."]', '["Allowing upper arms to drift forward and backward during reps.","Failing to lock out triceps fully at peak contraction."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Hip Lift with Band', 'GLUTES', 'CALVES,HAMSTRINGS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Lift_with_Band/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hip_Lift_with_Band/0.jpg', 'After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move.', '["After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move.","Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.","Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.","Pause at the top of the motion, and return to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Knee Across The Body', 'GLUTES', 'ABS,BACK', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Across_The_Body/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Knee_Across_The_Body/0.jpg', 'Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn''t need to touch the floor if you''re tight.)', '["Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn''t need to touch the floor if you''re tight.)","Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Kneeling Jump Squat', 'GLUTES', 'CALVES,HAMSTRINGS,QUADRICEPS', 'BARBELL', 'ADVANCED', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Jump_Squat/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kneeling_Jump_Squat/0.jpg', 'Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.', '["Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.","Sit back with your hips until your glutes touch your feet, keeping your head and chest up.","Explode up with your hips, generating enough power to land with your feet flat on the floor.","Continue with the squat by driving through your heels and extending the knees to come to a standing position."]', '["Allowing knees to cave inward (valgus collapse) during the upward drive phase.","Lifting heels off the ground and shifting weight excessively onto toes.","Rounding the lumbar spine at the bottom instead of maintaining neutral spinal bracing."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Rowing Machine Intervals', 'CARDIO', 'BACK,LEGS,BICEPS,ABS', 'MACHINE', 'INTERMEDIATE', 'https://images.unsplash.com/photo-1540497077202-7c8a3999166f?w=600', 'https://images.unsplash.com/photo-1540497077202-7c8a3999166f?w=400', 'Catch: Sit tall, shins vertical, arms extended forward, hinge slightly forward from hips.', '["Catch: Sit tall, shins vertical, arms extended forward, hinge slightly forward from hips.","Drive: Push explosively through feet and legs first, then swing torso back, and finish with arms pulling handle to sternum.","Finish: Legs straight, slight backward body lean, handle at lower ribs.","Recovery: Extend arms, hinge torso forward, then slide knees forward back to catch in a smooth 1:2 drive-to-recovery ratio."]', '["Bending knees before arms have cleared during recovery phase.","Pulling with arms before legs have completed the drive."]', 5, '500m split', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Jump Rope', 'CARDIO', 'CALVES,FOREARMS,SHOULDERS', 'BODYWEIGHT', 'BEGINNER', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=600', 'https://images.unsplash.com/photo-1598971639058-fab3c3109a00?w=400', 'Hold handles at hip height with elbows tucked close to torso.', '["Hold handles at hip height with elbows tucked close to torso.","Rotate rope using quick wrist flicks rather than large arm circles.","Bound softly on balls of feet 1-2 inches off floor with slight knee bend.","Maintain rhythm with relaxed breathing for set duration."]', '["Jumping too high and landing heavily on flat feet or heels.","Swinging arms from elbows or shoulders rather than wrists."]', 4, '60s', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('World''s Greatest Stretch', 'HAMSTRINGS', 'GLUTES,BACK,SHOULDERS,QUADRICEPS', 'BODYWEIGHT', 'BEGINNER', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=600', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?w=400', 'Step into a deep forward lunge with right foot forward and left leg extended back.', '["Step into a deep forward lunge with right foot forward and left leg extended back.","Place left hand on floor inside right foot. Drop right elbow down toward right instep to open hip.","Rotate torso toward front knee and reach right arm straight up toward ceiling.","Follow hand with eyes and hold for 2-3 breaths. Switch sides."]', '["Rushing through positions without relaxing into the stretch.","Letting front foot roll onto edge rather than staying grounded."]', 3, '5 per side', FALSE, 'FitTrack Curated Core Exercise Library & Anatomy Form Standard');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('90/90 Hamstring', 'HAMSTRINGS', 'CALVES', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/90_90_Hamstring/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/90_90_Hamstring/0.jpg', 'Lie on your back, with one leg extended straight out.', '["Lie on your back, with one leg extended straight out.","With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.","Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.","Repeat for 10-20 repetitions, and then switch to the other leg."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternating Hang Clean', 'HAMSTRINGS', 'BICEPS,CALVES,FOREARMS,GLUTES,BACK,TRAPS', 'KETTLEBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Hang_Clean/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Hang_Clean/0.jpg', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', '["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.","Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Ball Leg Curl', 'HAMSTRINGS', 'CALVES,GLUTES', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ball_Leg_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ball_Leg_Curl/0.jpg', 'Begin on the floor laying on your back with your feet on top of the ball.', '["Begin on the floor laying on your back with your feet on top of the ball.","Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.","Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.","Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.","After a brief pause, return to the starting position."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Band Good Morning', 'HAMSTRINGS', 'GLUTES,BACK', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Good_Morning/0.jpg', 'Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.', '["Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.","Keeping your legs straight, extend through the hips to come to a near vertical position.","Ensure that you do not round your back as you go down back to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Band Good Morning (Pull Through)', 'HAMSTRINGS', 'GLUTES,BACK', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning_Pull_Through/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Good_Morning_Pull_Through/0.jpg', 'Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.', '["Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.","Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.","Return to the starting position be driving through with the hips to come back to a standing position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Box Jump (Multiple Response)', 'HAMSTRINGS', 'ABS,QUADRICEPS,CALVES,GLUTES', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Jump_Multiple_Response/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Jump_Multiple_Response/0.jpg', 'Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.', '["Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.","Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.","Immediately drop or jump back down to the original starting place; then repeat the sequence."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Box Skip', 'HAMSTRINGS', 'ABS,QUADRICEPS,CALVES,GLUTES', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Skip/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Box_Skip/0.jpg', 'You will need several boxes lined up about 8 feet apart.', '["You will need several boxes lined up about 8 feet apart.","Begin facing the first box with one leg slightly behind the other.","Drive off the back leg, attempting to gain as much height with the hips as possible.","Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.","Then, step to the next box and repeat."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Chair Leg Extended Stretch', 'HAMSTRINGS', 'QUADRICEPS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Leg_Extended_Stretch/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chair_Leg_Extended_Stretch/0.jpg', 'Sit upright in a chair and grip the seat on the sides.', '["Sit upright in a chair and grip the seat on the sides.","Raise one leg, extending the knee, flexing the ankle as you do so.","Slowly move that leg outward as far as you can, and then back to the center and down.","Repeat for your other leg."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Clean', 'HAMSTRINGS', 'CALVES,FOREARMS,GLUTES,BACK,QUADRICEPS,SHOULDERS,TRAPS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean/0.jpg', 'With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', '["With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Clean Deadlift', 'HAMSTRINGS', 'FOREARMS,GLUTES,BACK,QUADRICEPS,TRAPS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Deadlift/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Clean_Deadlift/0.jpg', 'Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.', '["Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.","Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.","After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended."]', '["Rounding the lower back when breaking the bar off the floor.","Letting the barbell drift far away from shins during the pull.","Hyperextending the lower back at lockout rather than squeezing glutes through."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Double Kettlebell Alternating Hang Clean', 'HAMSTRINGS', 'BICEPS,CALVES,FOREARMS,GLUTES,BACK,QUADRICEPS,TRAPS', 'KETTLEBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Alternating_Hang_Clean/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Double_Kettlebell_Alternating_Hang_Clean/0.jpg', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', '["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean one kettlebell to your shoulder and hold on to the other kettlebell.","With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Dumbbell Clean', 'HAMSTRINGS', 'CALVES,FOREARMS,GLUTES,BACK,QUADRICEPS,SHOULDERS,TRAPS', 'DUMBBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Clean/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Clean/0.jpg', 'Begin standing with a dumbbell in each hand with your feet shoulder width apart.', '["Begin standing with a dumbbell in each hand with your feet shoulder width apart.","Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.","To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.","After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.","Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Floor Glute-Ham Raise', 'HAMSTRINGS', 'CALVES,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Glute-Ham_Raise/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Floor_Glute-Ham_Raise/0.jpg', 'You can use a partner for this exercise or brace your feet under something stable.', '["You can use a partner for this exercise or brace your feet under something stable.","Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.","Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.","Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position."]', '["Using overly heavy resistance and swinging the upper body.","Raising hands higher than elbows, shifting tension to the upper traps."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('3/4 Sit-Up', 'ABS', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/3_4_Sit-Up/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/0.jpg', 'Lie down on the floor and secure your feet. Your legs should be bent at the knees.', '["Lie down on the floor and secure your feet. Your legs should be bent at the knees.","Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.","Flex your hips and spine to raise your torso toward your knees.","At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.","Repeat for the recommended amount of repetitions."]', '["Pulling on the neck with hands instead of flexing the spine using abdominal contraction.","Swinging legs using hip flexor momentum rather than rolling the pelvis."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Ab Crunch Machine', 'ABS', '', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Crunch_Machine/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/0.jpg', 'Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.', '["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.","At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.","After a second pause, slowly return to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions."]', '["Pulling on the neck with hands instead of flexing the spine using abdominal contraction.","Swinging legs using hip flexor momentum rather than rolling the pelvis."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Ab Roller', 'ABS', 'SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Roller/0.jpg', 'Hold the Ab Roller with both hands and kneel on the floor.', '["Hold the Ab Roller with both hands and kneel on the floor.","Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Advanced Kettlebell Windmill', 'ABS', 'GLUTES,HAMSTRINGS,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Advanced_Kettlebell_Windmill/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/0.jpg', 'Clean and press a kettlebell overhead with one arm.', '["Clean and press a kettlebell overhead with one arm.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.","Lower yourself as far as possible.","Pause for a second and reverse the motion back to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Air Bike', 'ABS', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Air_Bike/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Air_Bike/0.jpg', 'Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.', '["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.","Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.","Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.","Go back to the initial position as you breathe in.","Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternate Heel Touchers', 'ABS', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Heel_Touchers/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/0.jpg', 'Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.', '["Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.","Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.","Now go back slowly to the starting position as you inhale.","Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.","Continue alternating sides in this manner until all prescribed repetitions are done."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Ab Rollout', 'ABS', 'BACK,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout/0.jpg', 'For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.', '["For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.","While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.","After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.","Repeat for the recommended amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Ab Rollout - On Knees', 'ABS', 'BACK,SHOULDERS', 'BARBELL', 'ADVANCED', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg', 'Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.', '["Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.","Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 4, '6-10', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Rollout from Bench', 'ABS', 'GLUTES,HAMSTRINGS,BACK,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rollout_from_Bench/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rollout_from_Bench/0.jpg', 'Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.', '["Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.","To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.","When the bar has been moved as far forward as possible, return to the starting position."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Side Bend', 'ABS', 'BACK', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Bend/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/0.jpg', 'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.', '["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bent-Knee Hip Raise', 'ABS', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Knee_Hip_Raise/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Knee_Hip_Raise/0.jpg', 'Lay flat on the floor with your arms next to your sides.', '["Lay flat on the floor with your arms next to your sides.","Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.","Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.","Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.","Repeat for the recommended amount of repetitions."]', '["Using overly heavy resistance and swinging the upper body.","Raising hands higher than elbows, shifting tension to the upper traps."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bent Press', 'ABS', 'GLUTES,HAMSTRINGS,BACK,QUADRICEPS,SHOULDERS,TRICEPS', 'KETTLEBELL', 'ADVANCED', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/0.jpg', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.', '["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.","Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.","Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '6-10', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bosu Ball Cable Crunch With Side Bends', 'ABS', '', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg', 'Connect a standard handle to each arm of a cable machine, and position them in the most downward position.', '["Connect a standard handle to each arm of a cable machine, and position them in the most downward position.","Grab a Bosu Ball and position it in front and center of the cable machine.","Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.","With both hands, reach back and grab the handle of each cable.","With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.","Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.","Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.","Repeat the same series of movements to failure.","Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.","Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques."]', '["Pulling on the neck with hands instead of flexing the spine using abdominal contraction.","Swinging legs using hip flexor momentum rather than rolling the pelvis."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bottoms Up', 'ABS', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms_Up/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms_Up/0.jpg', 'Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.', '["Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.","To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.","After a brief pause, return to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternate Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Hammer_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Hammer_Curl/0.jpg', 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', '["Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternate Incline Dumbbell Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg', 'Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.', '["Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.","While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbell back to starting position as your breathe in.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curl/0.jpg', 'Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.', '["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Curls Lying Against An Incline', 'BICEPS', '', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curls_Lying_Against_An_Incline/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curls_Lying_Against_An_Incline/0.jpg', 'Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.', '["Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.","While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.","After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.","Repeat for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Brachialis-SMR', 'BICEPS', '', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Brachialis-SMR/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Brachialis-SMR/0.jpg', 'Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.', '["Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.","Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable Hammer Curls - Rope Attachment', 'BICEPS', '', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg', 'Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.', '["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.","Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.","Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.","Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.","After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.","Repeat for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable Preacher Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Preacher_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Preacher_Curl/0.jpg', 'Place a preacher bench about 2 feet in front of a pulley machine.', '["Place a preacher bench about 2 feet in front of a pulley machine.","Attach a straight bar to the low pulley.","Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.","Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.","Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.","Now slowly lower the weight to the starting position.","Repeat for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Close-Grip EZ-Bar Curl with Band', 'BICEPS', 'FOREARMS', 'EZ_BAR', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg', 'Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.', '["Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.","While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Close-Grip EZ Bar Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ_Bar_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ_Bar_Curl/0.jpg', 'Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.', '["Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Close-Grip Standing Barbell Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Standing_Barbell_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Standing_Barbell_Curl/0.jpg', 'Hold a barbell with both hands, palms up and a few inches apart.', '["Hold a barbell with both hands, palms up and a few inches apart.","Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.","Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.","Slowly go back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Concentration Curls', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Concentration_Curls/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Concentration_Curls/0.jpg', 'Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.', '["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.","Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cross Body Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Body_Hammer_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Body_Hammer_Curl/0.jpg', 'Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.', '["Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.","While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.","Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.","Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Drag Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Drag_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drag_Curl/0.jpg', 'Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.', '["Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.","As you exhale, curl the bar up while keeping the elbows to the back as you \"Drag\" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.","Slowly go back to the starting position as you keep the bar in contact with the torso at all times.","Repeat for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Dumbbell Alternate Bicep Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Alternate_Bicep_Curl/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Alternate_Bicep_Curl/0.jpg', 'Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.', '["Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.","While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."]', '["Swinging the hips and torso backward to generate momentum.","Letting elbows flare forward rather than staying pinned close to ribs.","Short-changing the stretch at the bottom without full elbow extension."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternating Cable Shoulder Press', 'SHOULDERS', 'TRICEPS', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Cable_Shoulder_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Cable_Shoulder_Press/0.jpg', 'Move the cables to the bottom of the tower and select an appropriate weight.', '["Move the cables to the bottom of the tower and select an appropriate weight.","Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.","Keeping your head and chest up, extend through the elbow to press one side directly over head.","After pausing at the top, return to the starting position and repeat on the opposite side."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternating Deltoid Raise', 'SHOULDERS', '', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Deltoid_Raise/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Deltoid_Raise/0.jpg', 'In a standing position, hold a pair of dumbbells at your side.', '["In a standing position, hold a pair of dumbbells at your side.","Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.","Return the weights to your side.","On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.","Return the weights to the starting position and continue alternating to the front and side."]', '["Using overly heavy resistance and swinging the upper body.","Raising hands higher than elbows, shifting tension to the upper traps."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Alternating Kettlebell Press', 'SHOULDERS', 'TRICEPS', 'KETTLEBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternating_Kettlebell_Press/0.jpg', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.', '["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .","Lower the pressed kettlebell to the starting position and immediately press with your other arm."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Anti-Gravity Press', 'SHOULDERS', 'BACK,TRAPS,TRICEPS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anti-Gravity_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Anti-Gravity_Press/0.jpg', 'Place a bar on the ground behind the head of an incline bench.', '["Place a bar on the ground behind the head of an incline bench.","Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.","To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.","Return to the starting position and repeat to complete the set."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Arm Circles', 'SHOULDERS', 'TRAPS', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arm_Circles/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Arm_Circles/0.jpg', 'Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.', '["Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.","Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Arnold Dumbbell Press', 'SHOULDERS', 'TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Arnold_Dumbbell_Press/0.jpg', 'Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.', '["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.","Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.","Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.","After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Back Flyes - With Bands', 'SHOULDERS', 'BACK,TRICEPS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Back_Flyes_-_With_Bands/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Back_Flyes_-_With_Bands/0.jpg', 'Run a band around a stationary post like that of a squat rack.', '["Run a band around a stationary post like that of a squat rack.","Grab the band by the handles and stand back so that the tension in the band rises.","Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.","As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.","After a pause, go back to the original position as you inhale.","Repeat for the recommended amount of repetitions."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Backward Medicine Ball Throw', 'SHOULDERS', '', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Medicine_Ball_Throw/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Backward_Medicine_Ball_Throw/0.jpg', 'This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.', '["This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.","Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.","Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.","Your partner can then roll the ball back to you. Repeat for the desired number of repetitions."]', '["Yanking with lower back momentum rather than initiating with scapular retraction.","Shrugging shoulders into the neck instead of driving elbows back towards hip pocket."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Band Pull Apart', 'SHOULDERS', 'BACK,TRAPS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Pull_Apart/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Pull_Apart/0.jpg', 'Begin with your arms extended straight out in front of you, holding the band with both hands.', '["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Incline Shoulder Raise', 'SHOULDERS', 'CHEST', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Shoulder_Raise/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Incline_Shoulder_Raise/0.jpg', 'Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.', '["Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.","While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.","Bring back the bar to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."]', '["Using overly heavy resistance and swinging the upper body.","Raising hands higher than elbows, shifting tension to the upper traps."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Rear Delt Row', 'SHOULDERS', 'BICEPS,BACK', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rear_Delt_Row/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rear_Delt_Row/0.jpg', 'Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.', '["Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.","Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter \"T\". Now you are ready to begin the exercise.","While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.","Slowly go back to the initial position as you breathe in.","Repeat for the recommended amount of repetitions."]', '["Yanking with lower back momentum rather than initiating with scapular retraction.","Shrugging shoulders into the neck instead of driving elbows back towards hip pocket."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Shoulder Press', 'SHOULDERS', 'CHEST,TRICEPS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shoulder_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Shoulder_Press/0.jpg', 'Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).', '["Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).","Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the shoulders slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Battling Ropes', 'SHOULDERS', 'CHEST,FOREARMS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Battling_Ropes/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Battling_Ropes/0.jpg', 'For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.', '["For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.","Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.","As you let that arm drop to the starting position, raise the opposite side.","Continue alternating your left and right arms, whipping the ropes up and down as fast as you can."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'SHOULDERS', '', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg', 'Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.', '["Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.","While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.","Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.","After a one second contraction at the top, slowly lower the dumbbells back to the starting position.","Repeat the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Ankle Circles', 'CALVES', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_Circles/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ankle_Circles/0.jpg', 'Use a sturdy object like a squat rack to hold yourself.', '["Use a sturdy object like a squat rack to hold yourself.","Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.","When you are done with the right foot, then repeat with the left leg."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Anterior Tibialis-SMR', 'CALVES', '', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anterior_Tibialis-SMR/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Anterior_Tibialis-SMR/0.jpg', 'Begin seated on the ground with your legs bent and your feet on the floor.', '["Begin seated on the ground with your legs bent and your feet on the floor.","Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Balance Board', 'CALVES', 'HAMSTRINGS,QUADRICEPS', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Balance_Board/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Balance_Board/0.jpg', 'Place a balance board in front of you.', '["Place a balance board in front of you.","Stand up on it and try to balance yourself.","Hold the balance for as long as desired."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Barbell Seated Calf Raise', 'CALVES', '', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Seated_Calf_Raise/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Seated_Calf_Raise/0.jpg', 'Place a block about 12 inches in front of a flat bench.', '["Place a block about 12 inches in front of a flat bench.","Sit on the bench and place the ball of your feet on the block.","Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.","Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.","After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.","Repeat for the recommended amount of repetitions."]', '["Using overly heavy resistance and swinging the upper body.","Raising hands higher than elbows, shifting tension to the upper traps."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Calf Press', 'CALVES', '', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf_Press/0.jpg', 'Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.', '["Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.","Select an appropriate weight, and grasp the handles. This will be your starting position.","Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.","After a brief pause, reverse the motion and repeat."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Calf Press On The Leg Press Machine', 'CALVES', '', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press_On_The_Leg_Press_Machine/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf_Press_On_The_Leg_Press_Machine/0.jpg', 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.', '["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Calf Raise On A Dumbbell', 'CALVES', '', 'DUMBBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raise_On_A_Dumbbell/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf_Raise_On_A_Dumbbell/0.jpg', 'Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.', '["Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.","Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.","Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.","Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.","Repeat for the recommended amount of repetitions."]', '["Using overly heavy resistance and swinging the upper body.","Raising hands higher than elbows, shifting tension to the upper traps."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Calf Raises - With Bands', 'CALVES', '', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raises_-_With_Bands/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf_Raises_-_With_Bands/0.jpg', 'Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.', '["Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.","While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.","Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.","After a one second contraction, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."]', '["Using overly heavy resistance and swinging the upper body.","Raising hands higher than elbows, shifting tension to the upper traps."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Calf Stretch Elbows Against Wall', 'CALVES', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Elbows_Against_Wall/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf_Stretch_Elbows_Against_Wall/0.jpg', 'Stand facing a wall from a couple feet away.', '["Stand facing a wall from a couple feet away.","Lean against the wall, placing your weight on your forearms.","Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Calf Stretch Hands Against Wall', 'CALVES', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Hands_Against_Wall/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calf_Stretch_Hands_Against_Wall/0.jpg', 'Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.', '["Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.","Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.","Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Calves-SMR', 'CALVES', '', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calves-SMR/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Calves-SMR/0.jpg', 'Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.', '["Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.","Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Donkey Calf Raises', 'CALVES', '', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Donkey_Calf_Raises/0.jpg', 'For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.', '["For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.","Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."]', '["Using overly heavy resistance and swinging the upper body.","Raising hands higher than elbows, shifting tension to the upper traps."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Dumbbell Seated One-Leg Calf Raise', 'CALVES', '', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg', 'Place a block on the floor about 12 inches from a flat bench.', '["Place a block on the floor about 12 inches from a flat bench.","Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.","Now place the ball of your left foot on the block. This will be your starting position.","Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.","Slowly return to the starting position, stretching as far down as possible.","Repeat for your prescribed number of repetitions and then repeat with the right leg."]', '["Using overly heavy resistance and swinging the upper body.","Raising hands higher than elbows, shifting tension to the upper traps."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Foot-SMR', 'CALVES', '', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Foot-SMR/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Foot-SMR/0.jpg', 'This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.', '["This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.","Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Band Skull Crusher', 'TRICEPS', '', 'MACHINE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Skull_Crusher/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Band_Skull_Crusher/0.jpg', 'Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.', '["Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.","Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.","Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bench Dips', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Dips/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Dips/0.jpg', 'For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.', '["For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bench Press - Powerlifting', 'TRICEPS', 'CHEST,FOREARMS,BACK,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_Powerlifting/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_-_Powerlifting/0.jpg', 'Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', '["Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Bench Press with Chains', 'TRICEPS', 'CHEST,BACK,SHOULDERS', 'BARBELL', 'ADVANCED', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_with_Chains/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bench_Press_with_Chains/0.jpg', 'Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.', '["Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.","Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.","Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Board Press', 'TRICEPS', 'CHEST,FOREARMS,BACK,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Board_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Board_Press/0.jpg', 'Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.', '["Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.","Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Body-Up', 'TRICEPS', 'ABS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body-Up/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body-Up/0.jpg', 'Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.', '["Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.","Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.","Slowly lower your forearms back to the ground by allowing the elbows to flex.","Repeat."]', '["Using rapid momentum rather than a 2-second controlled eccentric tempo.","Neglecting core bracing throughout the full range of motion."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Body Tricep Press', 'TRICEPS', '', 'BODYWEIGHT', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body_Tricep_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Body_Tricep_Press/0.jpg', 'Position a bar in a rack at chest height.', '["Position a bar in a rack at chest height.","Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.","Begin by flexing the elbow, lowering yourself towards the bar.","Pause, and then reverse the motion by extending the elbows.","Progress from bodyweight by adding chains over your shoulders."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable Incline Triceps Extension', 'TRICEPS', '', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Incline_Triceps_Extension/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Incline_Triceps_Extension/0.jpg', 'Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.', '["Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.","Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.","Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.","Slowly go back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Allowing upper arms to drift forward and backward during reps.","Failing to lock out triceps fully at peak contraction."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable Lying Triceps Extension', 'TRICEPS', '', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Lying_Triceps_Extension/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Lying_Triceps_Extension/0.jpg', 'Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.', '["Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.","With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.","Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.","Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.","Hold for a second at the contracted position and repeat for the recommended amount of repetitions."]', '["Allowing upper arms to drift forward and backward during reps.","Failing to lock out triceps fully at peak contraction."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable One Arm Tricep Extension', 'TRICEPS', '', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg', 'With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.', '["With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.","Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.","As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.","Squeeze the triceps and hold for a second in this contracted position.","Slowly return the handle to the starting position.","Repeat for the recommended amount of repetitions and then perform the same movement with the other arm."]', '["Allowing upper arms to drift forward and backward during reps.","Failing to lock out triceps fully at peak contraction."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Cable Rope Overhead Triceps Extension', 'TRICEPS', '', 'CABLE', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg', 'Attach a rope to the bottom pulley of the pulley machine.', '["Attach a rope to the bottom pulley of the pulley machine.","Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.","Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out.","Repeat for the recommended amount of repetitions."]', '["Allowing upper arms to drift forward and backward during reps.","Failing to lock out triceps fully at peak contraction."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Chain Handle Extension', 'TRICEPS', '', 'MACHINE', 'INTERMEDIATE', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chain_Handle_Extension/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Chain_Handle_Extension/0.jpg', 'You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.', '["You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.","Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.","Pause at the lockout, and reverse the motion to return to the starting position."]', '["Allowing upper arms to drift forward and backward during reps.","Failing to lock out triceps fully at peak contraction."]', 3, '8-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Close-Grip Barbell Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg', 'Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', '["Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 4, '5-8', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, thumbnail_url, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution) KEY(name) VALUES ('Close-Grip Dumbbell Press', 'TRICEPS', 'CHEST,SHOULDERS', 'DUMBBELL', 'BEGINNER', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Dumbbell_Press/0.jpg', 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Dumbbell_Press/0.jpg', 'Place a dumbbell standing up on a flat bench.', '["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.","Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.","Initiate the movement by lowering the dumbbell to your chest.","Return to the starting position by extending the elbows."]', '["Flaring elbows outward beyond 75 degrees, placing excess strain on the rotator cuff.","Arching the lower back excessively or lifting hips completely off the bench.","Bouncing the barbell or dumbbells off the ribcage instead of controlling the turnaround."]', 3, '10-12', FALSE, 'Open dataset by free-exercise-db (Public Domain / The Unlicense). Creative Commons / Public Domain exercise media.');